import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Bot, Sparkles, ChevronDown } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { PROJECTS, PROCESS_STEPS, DEVELOPER_INFO, FAQS } from '../constants';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const AiAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'assistant', 
      content: 'Привет! Я цифровой аватар Алекса. \n\nРасскажите про вашу задачу: вы хотите автоматизировать текущий бизнес или запустить новый стартап?' 
    }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // System instruction for the model
  const systemInstruction = `You are Alex's AI Assistant. Alex is a Senior Frontend Developer and AI Automation Expert.
Your role is to represent Alex, answer questions about his services, portfolio, and process, and encourage potential clients to contact him.

Use the following context to answer questions:

About Alex:
${JSON.stringify(DEVELOPER_INFO)}

Portfolio Projects:
${JSON.stringify(PROJECTS)}

Process Steps:
${JSON.stringify(PROCESS_STEPS)}

Frequently Asked Questions:
${JSON.stringify(FAQS)}

Guidelines:
- Be professional, modern, and concise.
- Use emojis sparingly.
- Focus on value: speed, quality, automation.
- If asked about pricing, use the info from the projects or general range (150k - 500k+ RUB).
- If the user wants to start, direct them to the Contact form.
- You speak Russian.
`;

  // We maintain a reference to the chat session to keep history
  const chatRef = useRef<any>(null);

  const getChat = () => {
    if (!chatRef.current) {
      chatRef.current = ai.chats.create({
        model: 'gemini-2.5-flash-latest',
        config: {
          systemInstruction: systemInstruction,
        }
      });
    }
    return chatRef.current;
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue.trim()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsLoading(true);

    try {
      const chat = getChat();

      // Create a placeholder for the assistant's response
      const assistantMessageId = (Date.now() + 1).toString();
      setMessages(prev => [...prev, {
        id: assistantMessageId,
        role: 'assistant',
        content: ''
      }]);

      const result = await chat.sendMessageStream({ message: userMessage.content });

      let fullText = '';
      for await (const chunk of result) {
        const c = chunk as GenerateContentResponse;
        const text = c.text;
        if (text) {
          fullText += text;
          setMessages(prev => prev.map(msg => 
            msg.id === assistantMessageId 
              ? { ...msg, content: fullText }
              : msg
          ));
        }
      }

    } catch (error) {
      console.error('Gemini API Error:', error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'assistant',
        content: 'Извините, сейчас я не могу ответить. Пожалуйста, попробуйте позже или используйте форму контактов.'
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-8 right-8 z-50 p-4 rounded-full shadow-[0_0_20px_rgba(99,102,241,0.5)] transition-all duration-300 hover:scale-110 flex items-center justify-center ${isOpen ? 'bg-slate-800 text-white rotate-90' : 'bg-indigo-600 text-white hover:bg-indigo-500'}`}
        aria-label="Toggle AI Assistant"
      >
        {isOpen ? <X size={28} /> : <MessageCircle size={28} />}
      </button>

      {/* Chat Window */}
      <div 
        className={`fixed bottom-24 right-4 md:right-8 w-[90vw] md:w-[400px] h-[600px] max-h-[80vh] bg-slate-900/95 backdrop-blur-xl border border-slate-700/50 rounded-2xl shadow-2xl flex flex-col z-50 transition-all duration-300 origin-bottom-right ${isOpen ? 'opacity-100 scale-100' : 'opacity-0 scale-90 pointer-events-none translate-y-10'}`}
      >
        {/* Header */}
        <div className="p-4 border-b border-slate-800 flex items-center gap-3 bg-gradient-to-r from-indigo-900/50 to-slate-900 rounded-t-2xl">
          <div className="w-10 h-10 rounded-full bg-indigo-600 flex items-center justify-center shadow-lg relative">
            <Bot size={24} className="text-white" />
            <div className="absolute -bottom-1 -right-1 bg-green-500 w-3 h-3 rounded-full border-2 border-slate-900"></div>
          </div>
          <div>
            <h3 className="font-bold text-white flex items-center gap-2">
              Alex AI
              <span className="px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-300 text-[10px] font-bold uppercase tracking-wider border border-indigo-500/30">Gemini 2.5 Flash</span>
            </h3>
            <p className="text-xs text-indigo-300">Онлайн • Отвечает мгновенно</p>
          </div>
          <button onClick={() => setIsOpen(false)} className="ml-auto text-slate-400 hover:text-white">
            <ChevronDown size={20} />
          </button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
          {messages.map((msg) => (
            <div 
              key={msg.id} 
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div 
                className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-br-none shadow-lg' 
                    : 'bg-slate-800 border border-slate-700 text-slate-200 rounded-bl-none shadow-md'
                }`}
              >
                {msg.role === 'assistant' ? (
                  <div className="prose prose-invert prose-sm max-w-none">
                    <ReactMarkdown>{msg.content}</ReactMarkdown>
                  </div>
                ) : (
                  msg.content
                )}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-slate-800 border border-slate-700 p-4 rounded-2xl rounded-bl-none flex items-center gap-2">
                <Sparkles size={16} className="text-indigo-400 animate-pulse" />
                <span className="text-slate-400 text-xs animate-pulse">Alex AI печатает...</span>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <form onSubmit={handleSendMessage} className="p-4 border-t border-slate-800 bg-slate-900/50 rounded-b-2xl">
          <div className="relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Спросите про проекты или цены..."
              className="w-full bg-slate-950 border border-slate-700 rounded-xl pl-4 pr-12 py-3 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all"
            />
            <button 
              type="submit"
              disabled={!inputValue.trim() || isLoading}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 disabled:opacity-50 disabled:hover:bg-indigo-600 transition-colors"
            >
              <Send size={16} />
            </button>
          </div>
          <div className="text-center mt-2">
            <p className="text-[10px] text-slate-600">Powered by Gemini 2.5 Flash</p>
          </div>
        </form>
      </div>
    </>
  );
};

export default AiAssistant;

import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Bot, Sparkles, ChevronDown, AlertTriangle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { PROJECTS, PROCESS_STEPS, DEVELOPER_INFO, FAQS } from '../constants';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  isError?: boolean;
}

// Инициализация SDK. Ключ берется строго из окружения.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const AiAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'assistant', 
      content: 'Привет! Я цифровой аватар Алекса. Готов ответить на любые вопросы по проектам, стеку или ценам.' 
    }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Ref для хранения сессии чата, чтобы сохранять контекст диалога
  const chatRef = useRef<any>(null);

  // Формируем полный системный промпт без сокращений
  const systemInstruction = `You are Alex's AI Assistant. Alex is a Senior Frontend Developer and AI Automation Expert.
Your role is to represent Alex, answer questions about his services, portfolio, and process, and encourage potential clients to contact him.

CONTEXT DATA:

[DEVELOPER PROFILE]
${JSON.stringify(DEVELOPER_INFO, null, 2)}

[PORTFOLIO PROJECTS (Use this for pricing and examples)]
${JSON.stringify(PROJECTS, null, 2)}

[WORK PROCESS]
${JSON.stringify(PROCESS_STEPS, null, 2)}

[FAQ]
${JSON.stringify(FAQS, null, 2)}

INSTRUCTIONS:
1. Answer users' questions based STRICTLY on the provided context.
2. Be professional, modern, and concise.
3. If the user asks about prices, quote the specific prices from the Projects section or the general range.
4. If technical questions arise, showcase Alex's expertise (React, LLM, Automation).
5. Always speak in Russian unless the user speaks another language.
6. Do not invent facts not present in the context.
`;

  const getChat = () => {
    if (!chatRef.current) {
      // Строгое использование модели gemini-2.5-flash, как требовалось
      chatRef.current = ai.chats.create({
        model: 'gemini-2.5-flash',
        config: {
          systemInstruction: systemInstruction,
        }
      });
    }
    return chatRef.current;
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue.trim()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsLoading(true);

    try {
      const chat = getChat();

      // Создаем сообщение ассистента, которое будет наполняться стримом
      const assistantMessageId = (Date.now() + 1).toString();
      setMessages(prev => [...prev, {
        id: assistantMessageId,
        role: 'assistant',
        content: ''
      }]);

      const result = await chat.sendMessageStream({ message: userMessage.content });

      let fullText = '';
      for await (const chunk of result) {
        const c = chunk as GenerateContentResponse;
        const text = c.text;
        if (text) {
          fullText += text;
          setMessages(prev => prev.map(msg => 
            msg.id === assistantMessageId 
              ? { ...msg, content: fullText }
              : msg
          ));
        }
      }

    } catch (error: any) {
      console.error('Gemini API Error:', error);

      // Выводим точную причину ошибки пользователю
      const errorMessage = error instanceof Error ? error.message : JSON.stringify(error);

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'assistant',
        isError: true,
        content: `**Ошибка API:** ${errorMessage}`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-8 right-8 z-50 p-4 rounded-full shadow-[0_0_20px_rgba(99,102,241,0.5)] transition-all duration-300 hover:scale-110 flex items-center justify-center ${isOpen ? 'bg-slate-800 text-white rotate-90' : 'bg-indigo-600 text-white hover:bg-indigo-500'}`}
        aria-label="Toggle AI Assistant"
      >
        {isOpen ? <X size={28} /> : <MessageCircle size={28} />}
      </button>

      {/* Chat Window */}
      <div 
        className={`fixed bottom-24 right-4 md:right-8 w-[90vw] md:w-[400px] h-[600px] max-h-[80vh] bg-slate-900/95 backdrop-blur-xl border border-slate-700/50 rounded-2xl shadow-2xl flex flex-col z-50 transition-all duration-300 origin-bottom-right ${isOpen ? 'opacity-100 scale-100' : 'opacity-0 scale-90 pointer-events-none translate-y-10'}`}
      >
        {/* Header */}
        <div className="p-4 border-b border-slate-800 flex items-center gap-3 bg-gradient-to-r from-indigo-900/50 to-slate-900 rounded-t-2xl">
          <div className="w-10 h-10 rounded-full bg-indigo-600 flex items-center justify-center shadow-lg relative">
            <Bot size={24} className="text-white" />
            <div className="absolute -bottom-1 -right-1 bg-green-500 w-3 h-3 rounded-full border-2 border-slate-900"></div>
          </div>
          <div>
            <h3 className="font-bold text-white flex items-center gap-2">
              Alex AI
              <span className="px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-300 text-[10px] font-bold uppercase tracking-wider border border-indigo-500/30">v2.5 Flash</span>
            </h3>
            <p className="text-xs text-indigo-300">Live API Connection</p>
          </div>
          <button onClick={() => setIsOpen(false)} className="ml-auto text-slate-400 hover:text-white">
            <ChevronDown size={20} />
          </button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
          {messages.map((msg) => (
            <div 
              key={msg.id} 
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div 
                className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-br-none shadow-lg' 
                    : msg.isError 
                      ? 'bg-red-900/50 border border-red-500/50 text-red-200 rounded-bl-none'
                      : 'bg-slate-800 border border-slate-700 text-slate-200 rounded-bl-none shadow-md'
                }`}
              >
                {msg.isError && <AlertTriangle size={16} className="inline-block mr-2 mb-1" />}
                {msg.role === 'assistant' ? (
                  <div className="prose prose-invert prose-sm max-w-none break-words">
                    <ReactMarkdown>{msg.content}</ReactMarkdown>
                  </div>
                ) : (
                  msg.content
                )}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-slate-800 border border-slate-700 p-4 rounded-2xl rounded-bl-none flex items-center gap-2">
                <Sparkles size={16} className="text-indigo-400 animate-pulse" />
                <span className="text-slate-400 text-xs animate-pulse">Думаю...</span>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <form onSubmit={handleSendMessage} className="p-4 border-t border-slate-800 bg-slate-900/50 rounded-b-2xl">
          <div className="relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Введите сообщение..."
              className="w-full bg-slate-950 border border-slate-700 rounded-xl pl-4 pr-12 py-3 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all"
            />
            <button 
              type="submit"
              disabled={!inputValue.trim() || isLoading}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 disabled:opacity-50 disabled:hover:bg-indigo-600 transition-colors"
            >
              <Send size={16} />
            </button>
          </div>
          <div className="text-center mt-2 flex justify-between px-2">
            <p className="text-[10px] text-slate-600">Powered by Gemini 2.5 Flash</p>
          </div>
        </form>
      </div>
    </>
  );
};

export default AiAssistant;

